import pandas as pd,json,collections,numpy as np,glob,re
D=pd.read_parquet('/workspace/taco_verl/train.parquet');L={'user\n'+r.prompt[0]['content']+'\nassistant\n':i for i,r in D.iterrows()}
# Objective: preserve broad multi-test rows while removing demonstrably inconsistent tests and single-example shortcuts.
single={i for i,x in enumerate(D.extra_info)if x['n_tests']==1}
blank=set();case=set();whitespace=set();material=set()
def lines(x):return tuple(z.strip()for z in str(x).splitlines()if z.strip())
for i,r in D.iterrows():
 g=json.loads(r.reward_model['ground_truth']);dd=collections.defaultdict(list)
 for a,b in zip(g['inputs'],g['outputs']):dd[str(a)].append(str(b))
 for a,bs in dd.items():
  if len(set(bs))<2:continue
  if len({lines(b)for b in bs})==1:whitespace.add(i)
  elif len({' '.join(lines(b)).lower()for b in bs})==1:case.add(i)
  else:material.add(i)
 if any(not str(b).strip()for b in g['outputs']):blank.add(i)
obs=[]
for f in glob.glob('/workspace/rollout_data/*.jsonl'):
 for r in map(json.loads,open(f)):
  i=L[r['input']];obs.append((i,r['step'],r['score'],r['pass_rate']))
a=pd.DataFrame(obs,columns=['i','step','s','p'])
for name,ss in [('all',set()),('single',single),('single_blank_case',single|blank|case),('single_allconf',single|blank|case|whitespace|material)]:
 rem=set(range(len(D)))-ss;x=a[~a.i.isin(ss)]
 print(name,'remove',len(ss),'remain',len(rem),'observedacc',x.s.mean(),'pr',x.p.mean(),'first20',x[x.step<=20].s.mean(),'last20',x[x.step>=30].s.mean())
 print('nt mean median singles',np.mean([D.iloc[i].extra_info['n_tests']for i in rem]),np.median([D.iloc[i].extra_info['n_tests']for i in rem]))
print('overlap material/single',len(material&single),'case/single',len(case&single),'blank/single',len(blank&single))
print('candidate total',len(single|blank|case),'ids',sorted(single|blank|case))
PY

