arguments.command:
python3 -I - <<'PY'
import pandas as pd,json,re,collections,numpy as np
D=pd.read_parquet('/workspace/taco_verl/train.parquet');T=pd.read_parquet('/workspace/taco_verl/test.parquet')
def norm(x):
 if isinstance(x,list):x='\n'.join(map(str,x))
 return ' '.join(str(x).split())
def pairs(p):
 q=p.split('QUESTION:\n',1)[-1].rsplit('\nUse Standard Input format\nANSWER:',1)[0]
 # capture labelled sample/example Input...Output blocks non-greedily
 pats=[r'(?is)(?:sample\s*)?(?:example\s*)?input\s*:?[ \t]*\n(.*?)\n\s*(?:sample\s*)?(?:example\s*)?output\s*:?[ \t]*\n(.*?)(?=\n\s*(?:sample|example|input|output|constraint|note|explanation|-----|$))',
       r'(?is)-----Example Input-----\s*\n(.*?)\n-----Example Output-----\s*\n(.*?)(?=\n-----|\Z)']
 out=[]
 for pat in pats:
  for a,b in re.findall(pat,q):out.append((norm(a),norm(b)))
 return out
for name,d in [('train',D),('test',T)]:
 counts=collections.Counter();examples=[]
 for i,r in d.iterrows():
  pp=pairs(r.prompt[0]['content']);g=json.loads(r.reward_model['ground_truth']);gg={norm(a):norm(b) for a,b in zip(g['inputs'],g['outputs'])}
  counts['rows']+=1;counts['parsedrows']+=bool(pp);counts['pairs']+=len(pp)
  bad=[];missing=[]
  for a,b in pp:
   if a not in gg:missing.append((a,b))
   elif gg[a]!=b:bad.append((a,b,gg[a]))
  counts['missing']+=len(missing);counts['bad']+=len(bad);counts['badrows']+=bool(bad)
  if bad:examples.append((i,r.extra_info['problem_id'],len(g['inputs']),len(pp),len(missing),bad[:2]))
 print(name,counts)
 print('bad rows',examples[:80])
PY

