import pandas as pd,json,glob,collections,numpy as np
D=pd.read_parquet('/workspace/taco_verl/train.parquet');L={'user\n'+r.prompt[0]['content']+'\nassistant\n':i for i,r in D.iterrows()}
obs=[]
for f in glob.glob('/workspace/rollout_data/*.jsonl'):
 for r in map(json.loads,open(f)):
  i=L[r['input']];obs.append((i,r['step'],r['score'],r['pass_rate']))
a=pd.DataFrame(obs,columns=['i','step','s','p'])
# Compare thresholded coverage and binary contradictions on frozen evidence, capped to >=1200.
for name,pred in [
 ('nt<=1',lambda n:n<=1),('nt<=2',lambda n:n<=2),('nt<=3',lambda n:n<=3),('nt<=5',lambda n:n<=5),('nt<=10',lambda n:n<=10),
 ('1<=nt<=10',lambda n:1<=n<=10),('nt<90',lambda n:n<90),('nt<16',lambda n:n<16),('nt<=10 or 90<=nt<100',lambda n:n<=10 or 90<=n<100),
 ('nt<=10 and sample input',None)]:
 if pred is None:
  ss={i for i,r in D.iterrows()if r.extra_info['n_tests']<=10 and str(json.loads(r.reward_model['ground_truth'])['inputs'][0]).strip()in r.prompt[0]['content']}
 else:ss={i for i,x in enumerate(D.extra_info)if pred(x['n_tests'])}
 x=a[~a.i.isin(ss)];print(name,'remove',len(ss),'remain',len(D)-len(ss),'frozen kept',round(x.s.mean(),4),'pr',round(x.p.mean(),4),'first',round(x[x.step<=20].s.mean(),4),'last',round(x[x.step>=30].s.mean(),4))
# Examine exact tests counts and blank test cases per class.
for name,pred in [('sparse',lambda n:n<=10),('middle',lambda n:10<n<90),('dense',lambda n:n>=90)]:
 ids=[i for i,x in enumerate(D.extra_info)if pred(x['n_tests'])];vals=[];blanks=0;contra=0
 for i in ids:
  g=json.loads(D.iloc[i].reward_model['ground_truth']);ins=g['inputs'];outs=g['outputs'];vals.extend(map(len,map(str,outs)));blanks+=sum(not str(b).strip()for b in outs)
  d=collections.defaultdict(set)
  for a,b in zip(ins,outs):d[str(a)].add(str(b))
  contra+=any(len(v)>1for v in d.values())
 print(name,'rows',len(ids),'mean outlen',np.mean(vals),'blank cases',blanks,'contradict rows',contra)
