import re,collections,numpy as np,json,glob,os
p='/workspace/logs/qwen3_4b_instruct_2507_taco_fsdp_20261110_012754.log'
patterns={'nan':r'(?i)\bnan\b','inf':r'(?i)\binf\b','oom':r'(?i)out of memory','error':r'(?i)(traceback|runtimeerror|exception)','trunc':r'response_length/clip_ratio:([0-9.eE+-]+)','grad':r'actor/grad_norm:([0-9.eE+-]+)','step':r"Training Progress:.*?(\d+)/50"}
c=collections.Counter();tr=[];gr=[]
for line in open(p,errors='replace'):
 for k,pat in patterns.items():
  m=re.search(pat,line)
  if m:c[k]+=1
 m=re.search(r'response_length/clip_ratio:([0-9.eE+-]+)',line)
 if m:tr.append(float(m.group(1)))
 m=re.search(r'actor/grad_norm:([0-9.eE+-]+)',line)
 if m:gr.append(float(m.group(1)))
print(c,'clip max',max(tr),'grad range',min(gr),max(gr),'n',len(gr))
for f in sorted(glob.glob('/workspace/rollout_data/*.jsonl'),key=lambda x:int(os.path.basename(x).split('.')[0])):
 rs=[json.loads(x)for x in open(f)];steps={r['step']for r in rs};counts=collections.Counter(r['input']for r in rs)
 assert len(rs)==128 and len(counts)==16 and set(counts.values())=={8} and len(steps)==1
 assert all(r['score'] in [0.,1.] and r['acc']==r['score'] and 0<=r['pass_rate']<=1 for r in rs)
