14	export WANDB_DIR="${WANDB_DIR:-${LOG_DIR}}"
15	export WANDB_PROJECT="${WANDB_PROJECT:-verl_grpo_taco}"
16	export WANDB_MODE=offline
17	export WANDB_API_KEY=offline
18	
19	DEVICE=${DEVICE:-$(python3 -c 'import torch_npu' 2>/dev/null && echo npu || echo gpu)}
20	INFER_BACKEND=${INFER_BACKEND:-vllm}
21	
22	MODEL_PATH="${MODEL_PATH:-${VERL_ROOT}/Qwen3-4B-Instruct-2507}"
23	TRAIN_FILE="${TRAIN_FILE:-${VERL_ROOT}/taco_verl/train.parquet}"
24	TEST_FILE="${TEST_FILE:-${VERL_ROOT}/taco_verl/test.parquet}"
25	TACO_REWARD_PATH="${TACO_REWARD_PATH:-${VERL_ROOT}/verl/utils/reward_score/taco.py}"
26	
27	NNODES=${NNODES:-1}
28	NGPUS_PER_NODE=${NGPUS_PER_NODE:-4}
29	# GPU selection is inherited from the environment / launcher — don't pin device
30	# indices here (the original g37 rig used 4-7, which isn't portable). verl uses
31	# the first ${NGPUS_PER_NODE} visible devices. Set CUDA_VISIBLE_DEVICES in the
32	# environment only if you need to restrict to a subset.
33	if [ -n "${CUDA_VISIBLE_DEVICES:-}" ]; then
34	    export CUDA_VISIBLE_DEVICES
35	fi
36	
37	TRAIN_BATCH_SIZE=${TRAIN_BATCH_SIZE:-16}
38	PPO_MINI_BATCH_SIZE=${PPO_MINI_BATCH_SIZE:-16}
39	PPO_MICRO_BATCH_SIZE_PER_GPU=${PPO_MICRO_BATCH_SIZE_PER_GPU:-1}
40	LOG_PROB_MICRO_BATCH_SIZE_PER_GPU=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU:-1}
41	MAX_PROMPT_LENGTH=${MAX_PROMPT_LENGTH:-2048}
42	# 16384: the 2507 model writes long code; at 4096, 20% of sampled rollouts
43	# truncate and truncated rollouts never pass their tests (measured 2026-11-09:
44	# acc 30.3%@4096 -> 31.8%@8192 -> 33.8%@16384 on the held-out split, n=4 t0.7)
45	MAX_RESPONSE_LENGTH=${MAX_RESPONSE_LENGTH:-16384}
46	MAX_MODEL_LEN=$((MAX_PROMPT_LENGTH + MAX_RESPONSE_LENGTH))
47	
48	ACTOR_LR=${ACTOR_LR:-1e-6}
49	KL_LOSS_COEF=${KL_LOSS_COEF:-0.02}
50	USE_KL_LOSS=${USE_KL_LOSS:-True}
51	ENTROPY_COEFF=${ENTROPY_COEFF:-0.001}
52	
53	ROLLOUT_TP=${ROLLOUT_TP:-1}
54	ROLLOUT_GPU_MEM_UTIL=${ROLLOUT_GPU_MEM_UTIL:-0.5}
55	ROLLOUT_N=${ROLLOUT_N:-8}
56	VAL_TEMPERATURE=${VAL_TEMPERATURE:-0.7}
57	VAL_DO_SAMPLE=${VAL_DO_SAMPLE:-True}
58	REWARD_NUM_WORKERS=${REWARD_NUM_WORKERS:-32}
59	
60	PROJECT_NAME=${PROJECT_NAME:-verl_grpo_taco}
61	EXPERIMENT_NAME=${EXPERIMENT_NAME:-taco_qwen3_4b_2507_grpo}
62	TEST_FREQ=${TEST_FREQ:-50}
63	TOTAL_EPOCHS=${TOTAL_EPOCHS:-15}
64	TOTAL_TRAINING_STEPS=${TOTAL_TRAINING_STEPS:-400}
65	# save_freq must be >0 or verl skips the final save too; equal to total steps => only last ckpt.
66	SAVE_FREQ=${SAVE_FREQ:-${TOTAL_TRAINING_STEPS}}
67	USE_V1=${USE_V1:-False}
68	
69	case "${DEVICE}" in
70	    gpu) ;;
71	    npu) NGPUS_PER_NODE=${NGPUS_PER_NODE:-8} ;;
72	    *)
73	        echo "Unsupported DEVICE=${DEVICE}. Expected 'gpu' or 'npu'." >&2
74	        exit 1
75	        ;;
76	esac
77	
78	DATA=(
79	    algorithm.adv_estimator=grpo
80	    data.train_files=${TRAIN_FILE}
81	    data.val_files=${TEST_FILE}
82	    data.train_batch_size=${TRAIN_BATCH_SIZE}
83	    data.max_prompt_length=${MAX_PROMPT_LENGTH}
84	    data.max_response_length=${MAX_RESPONSE_LENGTH}
85	    data.filter_overlong_prompts=True
86	    data.truncation='error'
87	    data.dataloader_num_workers=0
88	    algorithm.use_kl_in_reward=False
89	)
90	
91	MODEL=(
92	    actor_rollout_ref.model.path=${MODEL_PATH}
93	    actor_rollout_ref.model.use_remove_padding=True
94	    actor_rollout_ref.model.enable_gradient_checkpointing=True
95	    +actor_rollout_ref.model.override_config.attn_implementation=sdpa
96	)
97	
98	ACTOR=(
99	    actor_rollout_ref.actor.optim.lr=${ACTOR_LR}
100	    actor_rollout_ref.actor.ppo_mini_batch_size=${PPO_MINI_BATCH_SIZE}
101	    actor_rollout_ref.actor.ppo_micro_batch_size_per_gpu=${PPO_MICRO_BATCH_SIZE_PER_GPU}
102	    actor_rollout_ref.actor.use_kl_loss=${USE_KL_LOSS}
103	    actor_rollout_ref.actor.kl_loss_coef=${KL_LOSS_COEF}
104	    actor_rollout_ref.actor.kl_loss_type=low_var_kl
105	    actor_rollout_ref.actor.entropy_coeff=${ENTROPY_COEFF}
106	    actor_rollout_ref.actor.fsdp_config.param_offload=False
107	    actor_rollout_ref.actor.fsdp_config.optimizer_offload=False
108	)
109	
110	ROLLOUT=(
111	    actor_rollout_ref.rollout.log_prob_micro_batch_size_per_gpu=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU}
112	    actor_rollout_ref.rollout.tensor_model_parallel_size=${ROLLOUT_TP}
113	    actor_rollout_ref.rollout.name=${INFER_BACKEND}
114	    actor_rollout_ref.rollout.gpu_memory_utilization=${ROLLOUT_GPU_MEM_UTIL}
115	    actor_rollout_ref.rollout.enable_chunked_prefill=False
116	    actor_rollout_ref.rollout.enforce_eager=False
117	    actor_rollout_ref.rollout.free_cache_engine=True
118	    actor_rollout_ref.rollout.max_model_len=${MAX_MODEL_LEN}
119	    actor_rollout_ref.rollout.max_num_batched_tokens=${MAX_MODEL_LEN}
120	    actor_rollout_ref.rollout.n=${ROLLOUT_N}
121	    actor_rollout_ref.rollout.val_kwargs.temperature=${VAL_TEMPERATURE}
122	    actor_rollout_ref.rollout.val_kwargs.do_sample=${VAL_DO_SAMPLE}
123	)
124	
125	REF=(
126	    actor_rollout_ref.ref.log_prob_micro_batch_size_per_gpu=${LOG_PROB_MICRO_BATCH_SIZE_PER_GPU}
127	    actor_rollout_ref.ref.fsdp_config.param_offload=True
128	)
129	
130	REWARD=(
131	    reward.num_workers=${REWARD_NUM_WORKERS}
132	    reward.reward_manager.name=naive
133	    reward.custom_reward_function.path=${TACO_REWARD_PATH}
134	    reward.custom_reward_function.name=compute_score
135	)
136	
137	TRAINER=(
138	    trainer.critic_warmup=0
139	    trainer.logger='["console","wandb"]'
140	    trainer.project_name=${PROJECT_NAME}
141	    trainer.experiment_name=${EXPERIMENT_NAME}
142	    trainer.rollout_data_dir=${ROLLOUT_DATA_DIR}
143	    trainer.validation_data_dir=${VALIDATION_DATA_DIR}
144	    trainer.n_gpus_per_node=${NGPUS_PER_NODE}
145	    trainer.nnodes=${NNODES}
146	    trainer.save_freq=${SAVE_FREQ}
147	    trainer.test_freq=${TEST_FREQ}
148	    trainer.total_epochs=${TOTAL_EPOCHS}
149	    trainer.total_training_steps=${TOTAL_TRAINING_STEPS}
150	    trainer.use_v1=${USE_V1}
151	)
152	
153	echo "Logging to ${LOG_FILE}"
154	export PYTHONPATH="${VERL_ROOT}:${PYTHONPATH:-}"
155	
156	python3 -m verl.trainer.main_ppo \
157	    "${DATA[@]}" \
158	    "${MODEL[@]}" \
159	    "${ACTOR[@]}" \
160	    "${ROLLOUT[@]}" \
161	    "${REF[@]}" \
162	    "${REWARD[@]}" \
163	    "${TRAINER[@]}" \
164	    "$@" \
165	    >"${LOG_FILE}" 2>&1
166

