import pandas as pd,json,collections,glob,os,numpy as np
tr=pd.read_parquet('/workspace/taco_verl/train.parquet');te=pd.read_parquet('/workspace/taco_verl/test.parquet')
for name,df in [('train',tr),('test',te)]:
 ids=df.extra_info.map(lambda x:int(x['problem_id'][len(name):])).to_numpy(); ns=df.extra_info.map(lambda x:x['n_tests']).to_numpy()
 print(name,'id monotonic',bool(np.all(np.diff(ids)>0)),'id range',ids.min(),ids.max(),'quarters sparse',[(int((ns[a:b]<=10).sum()),b-a)for a,b in [(0,len(df)//4),(len(df)//4,len(df)//2),(len(df)//2,3*len(df)//4),(3*len(df)//4,len(df))]])
 print('n tests quantiles',np.quantile(ns,[0,.1,.25,.5,.75,.9,1]))
# conflict variants ignoring outer whitespace only and case+whitespace
for name,df in [('train',tr),('test',te)]:
 ctr=collections.Counter(); examples=[]
 for _,r in df.iterrows():
  g=json.loads(r.reward_model['ground_truth']);d=collections.defaultdict(list)
  for x,y in zip(g['inputs'],g['outputs']):d[str(x)].append(str(y))
  for x,ys in d.items():
   if len(set(ys))<2:continue
   if len(set(y.strip() for y in ys))==1:ctr['format_rows']+=1;break
  else:
   for x,ys in d.items():
    if len(set(ys))<2:continue
    if len(set(y.strip().lower() for y in ys))==1:
     ctr['case_rows']+=1;examples.append((r.extra_info['problem_id'],x,ys));break
 print(name,ctr,'case ex',[(a,b,c[:4])for a,b,c in examples[:3]])
