def run_test(sample, test=None, debug=False, fail_debug=None):

    reliability_guard()
    _install_sigalrm()

    if debug:
        print(f'start = {datetime.now().time()}')

    try:
        in_outs = json.loads(sample['input_output'])
    except ValueError:
        in_outs = None
    if in_outs:
        if in_outs.get('fn_name') is None:
            which_type = CODE_TYPE.standard_input
            method_name = None
        else:
            which_type = CODE_TYPE.call_based
            method_name = in_outs['fn_name']

    if debug:
        print(f'loaded input_output = {datetime.now().time()}')

    if test is None:
        return in_outs
    elif test is not None:
        ctx = {"index": None, "inputs": None, "expected": None, "output": None, "error": None}
        results = _ResultList(fail_debug, ctx)
        sol = 'import sys\nimport time\nimport itertools\nfrom itertools import accumulate, product, permutations, combinations\nimport collections\nfrom collections import Counter, OrderedDict, deque, defaultdict, ChainMap\nfrom functools import lru_cache\nimport math\nfrom math import sqrt, sin, cos, tan, ceil, fabs, floor, gcd, exp, log, log2\nimport fractions\nfrom typing import List, Tuple\nimport numpy as np\nimport random\nimport heapq\nfrom heapq import *\n'
        if debug:
            print(f'loading test code = {datetime.now().time()}')

        if which_type == CODE_TYPE.call_based:
            sol += test
            if debug:
                print(f'sol = {sol}')
            signal.alarm(timeout)
            try:
                tmp_sol = _runtime_module().from_string('tmp_sol', '', sol)
                if 'class Solution' not in test:
                    tmp = tmp_sol
                else:
                    tmp = tmp_sol.Solution()
                signal.alarm(0)
            except Exception as e:
                signal.alarm(0)
                if debug:
                    print(f'type 0 compilation error = {e}')
                ctx["error"] = f"compile: {e!r}"
                results.append(-2)
                return results
            signal.alarm(0)

        elif which_type == CODE_TYPE.standard_input:

            tmp_test = test.split('\n')

            new_test = []
            for x in tmp_test:
                if (not x.startswith('from ')) and (
                        not x.startswith('import ')):
                    new_test.append('\t' + x + '\n')
                else:
                    new_test.append(x + '\n')
            tmp_test = new_test

            new_test = ''
            started = False
            for i in tmp_test:
                if i.startswith('\t') and not started:
                    new_test += 'stdin = sys.stdin\nstdout = sys.stdout\n'
                    new_test += 'def code():\n'
                    new_test += i
                    started = True
                elif started and ((i.startswith('from ')) or
                                  (i.startswith('import '))):
                    new_test += '\t' + i
                else:
                    new_test += i
            tmp_test = new_test

            sol += tmp_test
            if debug:
                print(f'sol = {sol}')
            method_name = 'code'
            signal.alarm(timeout)
            try:
                tmp_sol = _runtime_module().from_string('tmp_sol', '', sol)
                tmp = tmp_sol
                signal.alarm(0)
            except Exception as e:
                signal.alarm(0)
                if debug:
                    print(f'type 1 compilation error = {e}')
                ctx["error"] = f"compile: {e!r}"
                results.append(-2)
                return results
            signal.alarm(0)
        if debug:
            print(f'get method = {datetime.now().time()}')

        try:
            method = getattr(tmp,
                             method_name)
        except:
            signal.alarm(0)
            e = sys.exc_info()
            print(f'unable to get function error = {e}')
            ctx["error"] = f"getattr: {e!r}"
            results.append(-2)
            return results

        for index, inputs in enumerate(in_outs['inputs']):
            ctx["index"] = index
            ctx["inputs"] = _clip_debug(inputs)
            ctx["expected"] = _clip_debug(in_outs['outputs'][index])
            ctx["output"] = None
            ctx["error"] = None

            try:
                if isinstance(inputs[0], dict):
                    inputs = [{int(k): v for k, v in inputs[0].items()}]
            except:
                True
            try:
                if isinstance(in_outs['outputs'][index], dict):
                    in_outs['outputs'][index] = [{
                        int(k): v
                        for k, v in in_outs['outputs'][index].items()
                    }]
            except:
                True
            try:
                if isinstance(in_outs['outputs'][index][0], dict):
                    in_outs['outputs'][index] = [{
                        int(k): v
                        for k, v in in_outs['outputs'][index][0].items()
                    }]
            except:
                True

            if debug:
                print(
                    f'time: {datetime.now().time()} testing index = {index}  inputs = {inputs}, {type(inputs)}. type = {which_type}'
                )
            if which_type == CODE_TYPE.call_based:
                signal.alarm(timeout)
                faulthandler.enable()
                try:
                    output = method(*inputs)
                    ctx["output"] = output

                    if isinstance(output, tuple):
                        output = list(output)

                    tmp_result = output == in_outs['outputs'][index]
                    if isinstance(in_outs['outputs'][index],
                                  list) and in_outs['outputs'][index]:
                        tmp_result = tmp_result or (
                            output == in_outs['outputs'][index][0])

                    try:
                        if isinstance(output[0], tuple):
                            tmp_result = tmp_result or ([
                                list(x) for x in output
                            ] == in_outs['outputs'][index][0])
                    except:
                        True
                    results.append(tmp_result)

                    signal.alarm(0)
                except Exception as e:
                    signal.alarm(0)
                    faulthandler.disable()
                    if debug:
                        print(
                            f'Standard input runtime error or time limit exceeded error = {e}'
                        )
                    ctx["error"] = f"runtime: {e!r}"
                    results.append(-1)
                    continue
                faulthandler.disable()
                signal.alarm(0)
                if debug:
                    print(
                        f"outputs = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                    )
            elif which_type == CODE_TYPE.standard_input:
                faulthandler.enable()
                signal.alarm(timeout)
                passed = False

                if isinstance(inputs, list):
                    inputs = '\n'.join(inputs)
                if isinstance(in_outs['outputs'][index], list):
                    in_outs['outputs'][index] = '\n'.join(
                        in_outs['outputs'][index])

                with Capturing() as output:
                    try:
                        call_method(method, inputs)

                        signal.alarm(0)
                        passed = True
                    except Exception as e:

                        signal.alarm(0)
                        print(
                            f'Call-based runtime error or time limit exceeded error = {repr(e)}{e}'
                        )
                        ctx["error"] = f"runtime: {e!r}"
                        results.append(-1)
                    signal.alarm(0)
                ctx["output"] = list(output)

                if not passed:
                    if debug:
                        nl = '\n'
                        if not isinstance(inputs, list):
                            print(
                                f"not passed output = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs.replace(nl,' new-line ')}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                            )
                        else:
                            print(
                                f"not passed output = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                            )
                    continue

                if passed and debug:
                    print(
                        f"==> output = {output}, test outputs = {in_outs['outputs'][index]}"
                    )

                if custom_compare_(output, in_outs['outputs'][index]):
                    tmp_result = True
                    results.append(tmp_result)
                    continue

                if isinstance(output, tuple):
                    output = list(output)

                tmp_result = False
                try:
                    tmp_result = (output == [in_outs['outputs'][index]])
                    if isinstance(in_outs['outputs'][index], list):
                        tmp_result = tmp_result or (
                            output == in_outs['outputs'][index])
                        if isinstance(output[0], str):
                            tmp_result = tmp_result or ([
                                e.strip() for e in output
                            ] == in_outs['outputs'][index])
                except Exception as e:
                    if debug:
                        print(f'Failed check1 exception = {e}')
                    pass

                if tmp_result == True:
                    results.append(tmp_result)
                    continue

                if isinstance(in_outs['outputs'][index], list):
                    for tmp_index, i in enumerate(in_outs['outputs'][index]):
                        in_outs['outputs'][index][tmp_index] = i.split('\n')
                        in_outs['outputs'][index][tmp_index] = [
                            x.strip()
                            for x in in_outs['outputs'][index][tmp_index] if x
                        ]
                else:
                    in_outs['outputs'][index] = in_outs['outputs'][
                        index].split('\n')
                    in_outs['outputs'][index] = list(
                        filter(len, in_outs['outputs'][index]))
                    in_outs['outputs'][index] = list(
                        map(lambda x: x.strip(), in_outs['outputs'][index]))

                try:
                    tmp_result = (output == [in_outs['outputs'][index]])
                    if isinstance(in_outs['outputs'][index], list):
                        tmp_result = tmp_result or (
                            output == in_outs['outputs'][index])
                except Exception as e:
                    if debug:
                        print(f'Failed check2 exception = {e}')
                    pass

                if tmp_result == True:
                    results.append(tmp_result)
                    continue

                if isinstance(output, list):
                    output = list(filter(len, output))

                if debug:
                    nl = '\n'
                    if not isinstance(inputs, list):
                        print(
                            f"output = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs.replace(nl,' new-line ')}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                        )
                    else:
                        print(
                            f"output = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                        )

                if tmp_result == True:
                    results.append(tmp_result)
                    continue

                try:
                    tmp_result = (output == [in_outs['outputs'][index]])
                    if isinstance(in_outs['outputs'][index], list):
                        tmp_result = tmp_result or (
                            output == in_outs['outputs'][index])
                except Exception as e:
                    if debug:
                        print(f'Failed check3 exception = {e}')
                    pass

                try:
                    output_float = [float(e) for e in output]
