def flexible(t):return bool(re.search(r'(?i)(any\s+(?:case|capital)|case\s+(?:of\s+each\s+letter\s+)?(?:does\s+not|doesn.t)\s+matter|case\s+insensitive|upper\s+or\s+lower|lower\s+case\s+or\s+in\s+upper\s+case|lowercase\s+or\s+uppercase|each\s+letter.*case|any\s+letter\s+in\s+lower\s+case)',t))
def mixed(r):
 if flexible(r.prompt[0]['content']):return False
 g=json.loads(r.reward_model['ground_truth']);ins=list(map(str,g['inputs']));outs=list(map(str,g['outputs']));good=[bool(re.fullmatch(r'(?i)[\s]*(?:(?:yes|no)[\s]*)+',y))for y in outs]
 for allowed in [{'yes'},{'no'}]:
  idx=[i for i,y in enumerate(outs)if good[i]and set(x.lower()for x in re.findall('[A-Za-z]+',y))<=allowed]
  if len(idx)<2:continue
  words=collections.defaultdict(set)
  for i in idx:
   for x in re.findall('[A-Za-z]+',outs[i]):words[x.lower()].add(x)
  if any(len(v)>1 for v in words.values()):return True
  d=collections.defaultdict(set)
  for i in idx:d[ins[i]].add(outs[i])
  if any(len({y.lower()for y in ys})==1 and len(ys)>1 for ys in d.values()):return True
 return False
case={r.extra_info['problem_id']for _,r in D.iterrows()if mixed(r)};blank={'train627','train12292','train14413','train22812','train23891','train25179'};sel=case|blank
expected={'train8332','train9348','train11702','train11957','train12608','train15965','train17652','train19195','train19946','train21149','train23401','train23571','train23669','train23675','train627','train12292','train14413','train22812','train23891','train25179'}
assert sel==expected,(sel^expected)
print('VERIFIED REMOVE',len(sel),sorted(sel))
D['key']='user\n'+D.prompt.map(lambda x:x[0]['content'])+'\nassistant\n';M={r.key:r.extra_info['problem_id']for _,r in D.iterrows()};rows=[json.loads(x)for f in glob.glob('/workspace/rollout_data/*.jsonl')for x in open(f)];g=collections.defaultdict(list)
for r in rows:g[(r['step'],M[r['input']])].append(r)
for label,pids in [('selected',sel),('retained',set(M.values())-sel)]:
 v=[r for r in rows if M[r['input']]in pids];gr=[x for x in g.values()if M[x[0]['input']]in pids]
 print(label,'source_rows',len(pids),'observed_problems',len({M[r['input']]for r in v}),'generations',len(v),'acc',np.mean([r['score']for r in v]),'pass_rate',np.mean([r['pass_rate']for r in v]),'groups',len(gr),'allzero_groups',np.mean([max(r['score']for r in x)==0 for x in gr]),'positive_groups',np.mean([max(r['score']for r in x)>0 for x in gr]))
print('selected groups',[(st,pid,len(v),round(np.mean([r['score']for r in v]),4),round(np.mean([r['pass_rate']for r in v]),4))for(st,pid),v in sorted(g.items())if pid in sel])
