D=pd.read_parquet('/workspace/taco_verl/train.parquet');D['key']='user\n'+D.prompt.map(lambda x:x[0]['content'])+'\nassistant\n';M={r.key:r for _,r in D.iterrows()}
rows=[json.loads(x)for f in glob.glob('/workspace/rollout_data/*.jsonl')for x in open(f)]
# Compare coverage groups at equal problem difficulty proxies, and deterministic step trends.
# Specifically inspect sparse rows not simply one-test: exact group outcomes and per-ID position.
for cat,fn in [('one',lambda n:n==1),('2-10',lambda n:2<=n<=10),('11-15',lambda n:11<=n<=15),('16-89',lambda n:16<=n<90),('90+',lambda n:n>=90)]:
 v=[r for r in rows if fn(M[r['input']].extra_info['n_tests'])];g=collections.defaultdict(list)
 for r in v:g[(r['step'],r['input'])].append(r)
 print(cat,'source',sum(fn(r.extra_info['n_tests'])for _,r in D.iterrows()),'gens',len(v),'problems',len({r['input']for r in v}),'acc',np.mean([r['score']for r in v]),'pass',np.mean([r['pass_rate']for r in v]),'allzero',np.mean([max(x['score']for x in z)==0 for z in g.values()]))
# Are one-test GT inputs always displayed examples? enumerate 56 with no literal input occurrence.
